}

#header #header-extra-div-3 {
 position: absolute;
 top: -69px; left: 0; right: 0;
 height: 300px;
 background: url(https://scpko.wdfiles.com/local--files/theme%3Athe-buck-stops-here/logo_KO.png) center no-repeat;
 background-size: 260px;
 z-index: -1;
 pointer-events: none;
}

#header h1 {
 margin-left: 0;
 padding: 0;
 clear: both;
 float: none;
}

#header h2 {
 margin-left: 0;
 padding: 0;
 clear: both;
 float: none;
}

#header h1 a {
 color: transparent;
 font-size: 0px;
 font-family: 'YES24', 'Yusei Magic', sans-serif;
 letter-spacing: 0.5px;
}

#header h1 a::before {
 display: inline-block;
 width: 100%;
 text-align: center;
 content: "대한민국 지역사령부";
